import * as React from 'react';
import { cn } from '@/lib/utils';

export type StepperStep = {
  label: string;
  description?: string;
};

export type StepperProps = Omit<React.OlHTMLAttributes<HTMLOListElement>, 'onClick'> & {
  steps: StepperStep[];
  /** Zero-based index of the active step. */
  current: number;
  orientation?: 'horizontal' | 'vertical';
  /** Makes completed/upcoming steps clickable. */
  onStepClick?: (index: number) => void;
};

/**
 * Progress through a multi-step flow with proper semantics: an ordered list
 * where the active step carries aria-current="step" and each marker states
 * complete/current/upcoming in text, not only color.
 */
export const Stepper = React.forwardRef<HTMLOListElement, StepperProps>(function Stepper(
  { steps, current, orientation = 'horizontal', onStepClick, className, ...props },
  ref
) {
  return (
    <ol
      ref={ref}
      className={cn(
        'flex gap-4',
        orientation === 'vertical' ? 'flex-col' : 'flex-wrap items-start',
        className
      )}
      {...props}
    >
      {steps.map((step, index) => {
        const state = index < current ? 'complete' : index === current ? 'current' : 'upcoming';
        const interactive = Boolean(onStepClick);
        const content = (
          <>
            <span
              aria-hidden="true"
              className={cn(
                'flex h-7 w-7 shrink-0 items-center justify-center rounded-full border text-xs font-medium',
                state === 'complete' && 'border-primary bg-primary text-primary-foreground',
                state === 'current' && 'border-primary text-primary',
                state === 'upcoming' && 'border-border text-muted-foreground'
              )}
            >
              {state === 'complete' ? '✓' : index + 1}
            </span>
            <span className="min-w-0">
              <span className={cn('block text-sm', state === 'upcoming' ? 'text-muted-foreground' : 'font-medium')}>
                {step.label}
              </span>
              {step.description && (
                <span className="block text-xs text-muted-foreground">{step.description}</span>
              )}
              <span className="sr-only">
                {state === 'complete' ? ' (completed)' : state === 'current' ? ' (current step)' : ' (upcoming)'}
              </span>
            </span>
          </>
        );

        return (
          <li key={step.label} className="flex min-w-0 items-start gap-2">
            {interactive ? (
              <button
                type="button"
                onClick={() => onStepClick?.(index)}
                aria-current={state === 'current' ? 'step' : undefined}
                className="flex items-start gap-2 rounded-md text-left focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring"
              >
                {content}
              </button>
            ) : (
              <div aria-current={state === 'current' ? 'step' : undefined} className="flex items-start gap-2">
                {content}
              </div>
            )}
            {orientation === 'horizontal' && index < steps.length - 1 && (
              <span aria-hidden="true" className="mt-3.5 hidden h-px w-8 bg-border sm:block" />
            )}
          </li>
        );
      })}
    </ol>
  );
});

{
  "id": "stepper",
  "name": "Stepper",
  "tier": "molecule",
  "description": "Multi-step flow indicator: ordered list, aria-current step, text state for complete/current/upcoming.",
  "designIntent": "Wizards need orientation: where am I, what is done, what is next. A stepper built on an ordered list keeps the sequence structural and announces state in text, not just color.",
  "props": [
    {
      "name": "steps",
      "type": "{ label: string; description?: string }[]",
      "required": true,
      "description": "Ordered step definitions."
    },
    {
      "name": "current",
      "type": "number",
      "required": true,
      "description": "Zero-based index of the active step."
    },
    {
      "name": "orientation",
      "type": "'horizontal' | 'vertical'",
      "required": false,
      "defaultValue": "horizontal",
      "description": "Layout direction.",
      "enum": [
        "horizontal",
        "vertical"
      ]
    },
    {
      "name": "onStepClick",
      "type": "(index: number) => void",
      "required": false,
      "description": "Makes steps clickable (for revisit flows)."
    }
  ],
  "examples": [
    {
      "title": "Onboarding wizard",
      "code": "<Stepper\n  current={step}\n  steps={[{ label: 'Account' }, { label: 'Studio details' }, { label: 'Invite team' }, { label: 'Review' }]}\n/>",
      "description": "Current step is announced; completed steps show a check."
    }
  ],
  "antiPatterns": [
    {
      "title": "Don't use it for progress percentage",
      "explanation": "Use Progress for measurable 0-100 progress; Stepper is discrete stages.",
      "example": "// Avoid: 7 steps for an upload\n// Prefer: <Progress value={42} />"
    }
  ],
  "accessibility": [
    {
      "feature": "Sequence + state",
      "implementation": "Ordered list with aria-current=step and sr-only state text",
      "userRequirements": "Keep step labels short and parallel"
    }
  ],
  "contentGuidelines": [
    {
      "contentType": "Step labels",
      "guidelines": [
        "Verb or noun phrase",
        "Parallel grammar",
        "3-5 steps max"
      ],
      "goodExamples": [
        "Account",
        "Studio details",
        "Review"
      ],
      "badExamples": [
        "Step 1",
        "Now do this"
      ]
    }
  ],
  "compositionRules": [
    {
      "component": "Form",
      "relationship": "One Form (or Form step) per Stepper stage",
      "example": "<Stepper current={1} steps={steps} />"
    }
  ],
  "relatedComponents": [
    "Progress",
    "Tabs",
    "Form"
  ],
  "package": "@slipstream-ui/core",
  "importPath": "@slipstream-ui/core",
  "version": "0.6.0",
  "sourceDir": "stepper",
  "exportName": "Stepper"
}
